// Extract base64 PDF from binary data fetched in previous step
const binary = $('Fetch PDF Binary').first().binary;
const pdfBase64 = binary && binary.data ? binary.data.data : '';

// Pass through so Build Layer 1 can reference it
return [{ json: { pdfBase64 } }];

const genResponse = $('Call OpenAI - Layer 4').first().json;
const meta = $('Build Layer 4 Prompt').first().json;
const raw = genResponse.choices?.[0]?.message?.content;

function tryCloseJson(s) {
  s = s.trimEnd();
  while (s.endsWith(',')) s = s.slice(0, -1).trimEnd();
  const stack = []; let inStr = false; let esc = false;
  for (const ch of s) {
    if (esc) { esc = false; continue; }
    if (ch === '\\' && inStr) { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{' || ch === '[') stack.push(ch === '{' ? '}' : ']');
    else if (ch === '}' || ch === ']') stack.pop();
  }
  if (inStr) {
    const openIdx = s.lastIndexOf('"');
    const before = s.slice(0, openIdx).trimEnd();
    if (before.endsWith(',') || before.endsWith('{')) {
      s = before.endsWith(',') ? before.slice(0, -1).trimEnd() : before;
    } else { s += '"'; }
  }
  s = s.trimEnd();
  while (s.endsWith(',')) s = s.slice(0, -1).trimEnd();
  while (stack.length) s += stack.pop();
  return s;
}

let slides = null;

if (raw) {
  let cleaned = raw.trim();
  if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();

  let layer4;
  try { layer4 = JSON.parse(cleaned); } catch(e) {
    try { layer4 = JSON.parse(cleaned.replace(/\\(?!["\\\/bfnrtu])/g, '\\\\')); } catch(e2) {
      try { layer4 = JSON.parse(tryCloseJson(cleaned)); } catch(e3) { layer4 = null; }
    }
  }

  if (layer4) {
    // v1.3 schema: final_render_ready_json.slides
    const frj = layer4.final_render_ready_json || layer4.validation_result?.final_render_ready_json;
    if (frj?.slides?.length) {
      slides = frj.slides;
    }
  }
}

// Fallback: use Layer 3 styled slides, converting styled_components -> components
if (!slides?.length && meta.styledSlides?.length) {
  slides = meta.styledSlides.map(s => ({
    slide_number: s.slide_number,
    archetype: s.archetype,
    layout_variant: s.layout_variant || '',
    background: { fill: '#FFFFFF' },
    components: (s.styled_components || s.components || []),
    chart_layout: s.chart_layout || s.chart_style || {},
    table_layout: s.table_layout || s.table_style || {},
    image_layout: s.image_layout || {},
    speaker_notes: s.speaker_notes || '',
  }));
}

if (!slides?.length) throw new Error('No slides produced by any layer');

// Normalize: ensure each slide has components[] not styled_components[]
for (const s of slides) {
  if (!s.components && s.styled_components) s.components = s.styled_components;
  if (!s.components) s.components = [];
  if (!s.background) {
    const bg = s.components.find(c => c.semantic_role === 'slide_background');
    s.background = { fill: bg?.style?.fill || '#FFFFFF' };
  }
}

// Inject image_generation_prompt from L1 into slides (for image generation nodes)
const l1Slides = meta.layer1Plan?.slides || [];
const imgPromptMap = {};
for (const s of l1Slides) {
  if (s.slide_number && s.image_generation_prompt) {
    imgPromptMap[s.slide_number] = s.image_generation_prompt;
  }
}
for (const s of slides) {
  if (!s.image_generation_prompt && imgPromptMap[s.slide_number]) {
    s.image_generation_prompt = imgPromptMap[s.slide_number];
  }
  // Also check image_layout
  if (!s.image_generation_prompt && s.image_layout?.image_prompt) {
    s.image_generation_prompt = s.image_layout.image_prompt;
  }
}

const body = $('Webhook').first().json.body;
const brandData = $('Fetch Brand Data').first().json;

return [{
  json: {
    brandId: body.brandId,
    jobId: body.jobId,
    brandName: meta.layer1Plan ? (brandData.brands?.name || 'Unknown') : 'Unknown',
    presentationTitle: meta.layer1Plan?.global_theme || slides[0]?.components?.find(c => c.semantic_role === 'slide_title')?.content || 'Presentation',
    brandPalette: meta.brandPalette || {},
    layer1Plan: meta.layer1Plan,
    renderReadyPlan: { slides },
    slideCount: slides.length,
    validationStatus: 'complete',
    correctionCount: 0,
  }
}];

const meta = $('Parse Final Output').first().json;
const slides = meta.renderReadyPlan.slides;
const brandName = meta.brandName;

const coverSlide = slides.find(s => s.archetype === 'title_cover');
const imgPrompt = coverSlide?.image_generation_prompt || '';
const prompt = imgPrompt
  ? `Professional ${brandName} brand presentation visual. ${imgPrompt}. Cinematic photography or clean illustration. No text, no logos, no watermarks. Corporate, brand-appropriate aesthetic.`
  : `Professional ${brandName} brand cover image. Modern corporate aesthetic. No text, no logos.`;

return [{ json: {
  ...meta,
  requestBody: JSON.stringify({
    model: 'gpt-image-2',
    prompt,
    size: '1024x1024',
    quality: 'medium',
    n: 1
  })
} }];

const imgResponse = $('Generate Cover Image').first().json;
const meta = $('Build Cover Image Prompt').first().json;
const slides = JSON.parse(JSON.stringify(meta.renderReadyPlan.slides));

const b64 = imgResponse.data?.[0]?.b64_json;
if (!b64) throw new Error('No b64_json from image API: ' + JSON.stringify(imgResponse).slice(0,300));

for (let i = 0; i < slides.length; i++) {
  if (slides[i].archetype !== 'title_cover') continue;
  const comps = slides[i].components || [];

  // Find existing image_placeholder component to update
  const imgCompIdx = comps.findIndex(c =>
    c.component_type === 'image_placeholder' ||
    c.semantic_role === 'image_placeholder' ||
    c.semantic_role === 'slide_image'
  );

  const imageComp = {
    id: 'el_img_cover',
    semantic_role: 'image_placeholder',
    component_type: 'image_placeholder',
    content: '',
    x: 960, y: 0, width: 960, height: 1080,
    zIndex: 4,
    editable_in_ppt: false,
    render_mode: 'image_placeholder',
    safeAreaCritical: false,
    image_url: 'data:image/png;base64,' + b64,
    style: { fill: '#1a1a1a', border_radius: 0 }
  };

  if (imgCompIdx >= 0) {
    slides[i].components[imgCompIdx] = { ...slides[i].components[imgCompIdx], image_url: 'data:image/png;base64,' + b64 };
  } else {
    slides[i].components = [imageComp, ...comps];
  }
  break;
}

return [{ json: {
  brandId: meta.brandId,
  jobId: meta.jobId,
  brandName: meta.brandName,
  presentationTitle: meta.presentationTitle,
  brandPalette: meta.brandPalette,
  layer1Plan: meta.layer1Plan,
  renderReadyPlan: { slides },
  slideCount: slides.length,
  validationStatus: meta.validationStatus,
  correctionCount: meta.correctionCount
} }];

const meta = $('Inject Cover Image').first().json;
const slides = meta.renderReadyPlan.slides;
const brandName = meta.brandName;

// Find ALL image_feature slides with prompts
const imgSlides = slides.filter(s => s.archetype === 'image_feature' && s.image_generation_prompt);
const imgSlide = imgSlides[0] || null;

const prompt = imgSlide
  ? `Professional ${brandName} brand visual for a presentation slide. ${imgSlide.image_generation_prompt}. Clean business photography or illustration. No text overlay, no logos, no watermarks. High quality corporate aesthetic.`
  : `Professional ${brandName} brand abstract visual. Modern corporate photography, clean and minimal. No text, no logos, no watermarks.`;

return [{ json: {
  ...meta,
  targetSlideNumber: imgSlide ? imgSlide.slide_number : null,
  additionalImgSlides: imgSlides.slice(1).map(s => s.slide_number),
  requestBody: JSON.stringify({
    model: 'gpt-image-2',
    prompt,
    size: '1024x1024',
    quality: 'medium',
    n: 1
  })
} }];

const imgResponse = $('Generate Slide Image').first().json;
const meta = $('Build Slide Image Prompt').first().json;
const slides = JSON.parse(JSON.stringify(meta.renderReadyPlan.slides));

const b64 = imgResponse.data?.[0]?.b64_json;
const targetNum = meta.targetSlideNumber;

if (b64 && targetNum) {
  for (let i = 0; i < slides.length; i++) {
    if (slides[i].slide_number !== targetNum) continue;
    const comps = slides[i].components || [];

    // Find the image_placeholder component for this slide
    const imgIdx = comps.findIndex(c =>
      c.component_type === 'image_placeholder' ||
      c.semantic_role === 'image_placeholder' ||
      c.semantic_role === 'visual_zone'
    );

    if (imgIdx >= 0) {
      slides[i].components[imgIdx] = {
        ...slides[i].components[imgIdx],
        image_url: 'data:image/png;base64,' + b64
      };
    } else {
      // Add as new full-right-side image component
      slides[i].components = [{
        id: 'el_img_slide_' + targetNum,
        semantic_role: 'image_placeholder',
        component_type: 'image_placeholder',
        content: '',
        x: 980, y: 140, width: 820, height: 740,
        zIndex: 4,
        editable_in_ppt: false,
        render_mode: 'image_placeholder',
        safeAreaCritical: false,
        image_url: 'data:image/png;base64,' + b64,
        style: { fill: '#DADDDD', border_radius: 0 }
      }, ...comps];
    }
    break;
  }
}

return [{ json: {
  brandId: meta.brandId,
  jobId: meta.jobId,
  brandName: meta.brandName,
  presentationTitle: meta.presentationTitle,
  brandPalette: meta.brandPalette,
  renderReadyPlan: { slides },
  slideCount: slides.length,
  validationStatus: meta.validationStatus,
  correctionCount: meta.correctionCount
} }];
